CREATE FUNCTION public.prepare_notification_reminders() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
INSERT INTO public.notification_events(user_id,category,source_kind,source_id,source_group,event_key) SELECT c.client_id,'checkins','checkin_due',r.id,r.id,'due:'||r.id FROM public.coaching_requests r JOIN public.coach_clients c ON c.id=r.relationship_id JOIN public.profiles p ON p.id=c.client_id WHERE c.state='active' AND NOT r.cancelled AND r.submitted_at IS NULL AND r.due_date=(now() AT TIME ZONE p.timezone)::date AND NOT EXISTS(SELECT 1 FROM public.notification_events n WHERE n.user_id=c.client_id AND n.event_key='due:'||r.id) ORDER BY r.id LIMIT 200 ON CONFLICT DO NOTHING;
INSERT INTO public.notification_events(user_id,category,source_kind,source_id,source_group,event_key,source_revision) SELECT who.id,'calendar','appointment_reminder',a.id,a.id,'appointment-reminder:'||a.id||':'||a.revision,a.revision FROM public.appointments a JOIN public.coach_clients c ON c.id=a.relationship_id CROSS JOIN LATERAL (VALUES(c.coach_id),(c.client_id))who(id) WHERE c.state='active' AND a.state='booked' AND a.starts_at>now() AND a.starts_at<=now()+interval '24 hours' AND NOT EXISTS(SELECT 1 FROM public.notification_events n WHERE n.user_id=who.id AND n.event_key='appointment-reminder:'||a.id||':'||a.revision) ORDER BY a.starts_at,a.id,who.id LIMIT 200 ON CONFLICT DO NOTHING;
INSERT INTO public.notification_events(user_id,workspace_id,category,source_kind,source_id,source_group,event_key,source_revision) SELECT m.user_id,e.workspace_id,'calendar','organization_reminder',e.id,e.id,'organization-reminder:'||e.id||':'||e.revision,e.revision FROM public.organization_events e JOIN public.organization_event_people p ON p.event_id=e.id JOIN public.workspace_members m ON m.id=p.member_id JOIN public.workspaces w ON w.id=e.workspace_id WHERE m.active AND m.user_id IS NOT NULL AND NOT w.archived AND e.state='scheduled' AND e.starts_at>now() AND e.starts_at<=now()+interval '24 hours' AND NOT EXISTS(SELECT 1 FROM public.notification_events n WHERE n.user_id=m.user_id AND n.event_key='organization-reminder:'||e.id||':'||e.revision) ORDER BY e.starts_at,e.id,m.id LIMIT 200 ON CONFLICT DO NOTHING;
END;
$$;
REVOKE ALL ON FUNCTION public.prepare_notification_reminders() FROM PUBLIC,rafik_guest,rafik_user;
GRANT EXECUTE ON FUNCTION public.prepare_notification_reminders() TO rafik_api;
